  "powerSettings.interestRulesLate": "One saved compound interest stream: current unspent bank × actual rate × earned/Joker/Poker boosts, with no payment ceiling. One replay-stable roll per genuine payment: ×2 from50; 10% chance of×3 from62. At80 earned cadence takes over; the saved choice remains.",
