  "settings.emeraldPlacement.note": "On roomy desktops, Left and Right sit beside the table. Smaller screens keep those alignments in a reserved area below. Below centers Emerald underneath. Choosing a position pauses floating Following without erasing its saved preference. Turn Following on to resume it.",
  "expansion.reward.51": "Unlock8 Settings power switches: Compound Interest, Passive Money, Passive XP, username display, card games, statistics, surveys and Market. Each switch turned OFF adds3% BATTERY LIFE, up to+24% for all8; no charging-speed bonus. Saved choices and history are retained, never deleted. Essential charging, drain, saving and recovery keep their existing rules.",
  "expansion.compact.51": "8 Settings power switches · +3% battery life/OFF (max+24%)",
  "expansion.reward.52": "New earned XP doubles from now on: ×2 applied ONCE. Compound interest uses this earned boost without a payment ceiling. Already-final awards are not doubled again. Historical XP and saved balances are not rewritten.",
  "expansion.compact.52": "New earned XP×2 ONCE before caps · historical XP unchanged",
  "expansion.reward.53": "Base CRIT chance increases by1 percentage point:1%→2%. This changes the base chance, not existing CRIT multipliers or historical scores.",
  "expansion.compact.53": "Base CRIT1%→2% (+1 percentage point)",
  "expansion.reward.54": "Final score gains10%, applied ONCE then rounded down: floor(previous final score ×1.10). Existing card and Joker effects are not reapplied; historical scores stay unchanged.",
  "expansion.compact.54": "Final score×1.10 ONCE · rounded down",
