  "expansion.deck.red": "+2 discards every round.",
  "expansion.deck.blue": "+2 hands every round.",
  "expansion.deck.yellow": "Start with $16 extra.",
  "expansion.deck.green": "No interest. At winning cashout earn $3 per remaining hand, $2 per remaining discard, and $1 extra per completed round.",
  "expansion.deck.black": "+2 Joker slots; -1 hand size. No hand-count penalty.",
  "expansion.deck.magic": "Start with Omen Globe, Crystal Ball and two copies of The Fool.",
  "expansion.deck.nebula": "Start with Telescope and Observatory; no consumable-slot penalty.",
  "expansion.deck.ghost": "Exactly 20% of ordinary shop shelf selections are Spectral. Start with Hex and Ankh.",
  "expansion.deck.abandoned": "Start with Ride the Bus and 40 cards: no Jacks, Queens or Kings.",
  "expansion.deck.checkered": "Start with exactly 80 cards: 40 Hearts and 40 Spades. Each suit adds A, K, Q, J, 10 through 2, A to its original 26 cards.",
  "expansion.deck.zodiac": "Start with Tarot Merchant, Tarot Tycoon, Planet Merchant, Planet Tycoon, Overstock, Overstock Plus, Reroll Surplus and Reroll Glut.",
  "expansion.deck.painted": "+3 hand size; -1 Joker slot.",
  "expansion.deck.anaglyph": "Gain two Double Tags after each real Boss Blind.",
  "expansion.deck.plasma": "Balance Chips and Mult to their average before multiplication. Normal Blind requirements.",
  "expansion.deck.erratic": "The saved seed independently sets starting hands, discards, hand size, Joker slots, consumable slots and Bank to 1–10 each; ranks and suits are randomized separately.",
  "expansion.deck.copper": "Earn $5 extra at every winning round cashout.",
  "expansion.deck.scholar": "Every poker hand, including custom hands, starts at Level 3.",
  "expansion.deck.twilight": "+2 hand size and +2 consumable slots.",
  "expansion.deck.prism": "All 52 starting cards are Wild. Start with The Tribe.",
  "expansion.deck.sprout": "Starting ranks 2–10 are Bonus cards: +30 Chips when scored.",
  "expansion.reward.35": "Cleaner battery presentation; all earlier rewards stay active.",
  "expansion.reward.40": "Tap the battery percentage for remaining charge, time estimate and full battery rules.",
  "expansion.reward.42": "Compound interest uses the current bank ×0.025%, with no payment ceiling. Native900 ms remains unless a saved choice applies. The Settings row stays read-only until44; actual100 earns0.",
  "expansion.reward.43": "+1 hand size. Compound interest remains current bank × actual rate × earned/Joker/Poker boosts, with no payment ceiling; native900 ms and ×0.025% remain unless a saved choice applies.",
  "expansion.reward.44": "Unlock all11 interval/rate choices for ONE shared interest stream in Settings. The separate Level42/44/46/48/50 rows all edit the same saved choice, not separate payments. Both500 ms choices are distinct: ×0.014% and ×0.01%. A saved custom choice overrides native timing/rate; with none saved, native800 ms and ×0.025% remain. no payment ceiling; actual100 earns0.",
  "expansion.reward.45": "All 20 enhanced starting decks unlock for NEW runs only. Saved ongoing runs keep their original deck perks. Erratic independently rolls six starting stats from 1 to 10; native modifiers still apply.",
  "expansion.reward.46": "New survey questionnaires have 40% fewer questions: ceil(original ×0.6), minimum 1, for every provider. Pending quizzes, CAPTCHA, consent, instruction checks and rewards stay intact. With no saved custom choice, native interest is700 ms at ×0.025%, no payment ceiling. A saved choice overrides native timing/rate; the Settings row edits the same ONE stream. Actual100 earns0.",
  "expansion.reward.47": "Stock Market maximum stake rises to game$20, using actual player level. The ten-minute deadline, risks, 1.5× gross return and no-real-money rules are unchanged.",
  "expansion.reward.48": "Emerald moves 50% faster in addition to his own E3 speed: ×1.5, or ×1.8 with E3. Motion preferences still apply. With no saved custom choice, native interest is600 ms at ×0.025%, no payment ceiling. A saved choice overrides native timing/rate; the Settings row edits the same ONE stream. Actual100 earns0.",
  "expansion.reward.49": "Emerald gains over 1,000 additional original contextual messages in English, Spanish and French: cards, games, kind reflections and respectful Bible-inspired ideas. Survey-completion remarks require a real saved completion; no hidden-card or RNG predictions.",
  "expansion.reward.50": "Cleaner colourful interface, reflective battery polish and less settings clutter; Low Power, chosen fonts and reduced motion remain respected. With no saved custom choice, native interest is500 ms at current bank ×0.025%, no payment ceiling. A saved choice overrides native timing/rate; the Settings row edits the same ONE stream. One eligible second may contain two native payments; actual100 earns0.",
  "expansion.compact.35": "6 Joker slots + 6-card selection + Frenzy166 + custom hands + $2/round + battery polish",
  "expansion.compact.40": "Passive Money + battery percentage opens details",
