  "battery.displayHelp": "Display only: no charge, session or cooldown changes. Compact shows the percentage inside the battery; tap it for controls. Recovery controls remain visible at 0%.",
  "battery.displaySaved": "Battery display saved.",
  "battery.displayPaused": "Battery display saving is uncertain. Reload safely; do not clear data or retry.",
  "battery.powerRules": "Light is visibly brighter and Dark dimmer; at 0% the game stays pitch black except Emerald and recovery controls. Low Power halves charging speed. Actual Player Level 55 doubles charging speed; both together restore the base speed. At actual Level 51+, each disabled feature adds 3% battery life: drain divides by 1 + 0.03 × disabled count (up to 8). This bonus never speeds charging or changes cooldown.",
