  "battery.unsafePrice": "Next price exceeds safe precision; keep your save.",
  "battery.empty": "Battery empty. Emerald, your player lamp, charging, battery help and Settings stay visible.",
  "battery.rules": "This is a FICTIONAL game battery, separate from your real device battery and its chip bonus. It starts at 100% only when you explicitly activate it or first use an eligible game. Only actual Player Level 25+ is active. Default drain is 1 percentage point/minute; Light replaces it with 2, Dark with 0.5, and Low Power replaces all three with 0.2. Above 80%, drain is doubled; 80–20% is normal, 20–5% takes 50% longer, and 5–0% takes twice as long. Brightness follows charge; there is no brightness slider.",
  "battery.chargeRules": "Click Charge to start a 30-minute eligible session. Positive charging REPLACES drain: charger 1 adds 0.80 percentage points per MINUTE (24 points in 30 minutes); charger 2 adds 0.82 (24.6 points), then +0.02 per level. Charging stops at 100%, or 80% with Adaptive, then a 10-minute eligible cooldown starts. Upgrades cost 20, 30, 40… virtual faucet coins; never poker Bank. No auto-restart. Changing Adaptive below the current charge stops the session immediately.",
  "battery.clockRules": "Only visible, writable eligible game time counts. Hidden, offline, other-tab, protected dialog, survey and cloud/slot replacement time never catches up. Remaining session/cooldown time survives reloads. Each active charged second may play one native SFX chime after your audio gesture; mute/SFX settings apply and delayed ticks never burst sounds.",
  "battery.notices": "Warnings occur only on real downward crossings of 10%, 5% and 3%, once per threshold until charging rises above it again. Rendering and reload never notify or award anything.",
  "battery.warning": "Low fictional battery: {percent}%. Charge is available from the battery control.",
