  "chill.unlock": "Baccarat and High-Low unlock at this own level: free tables with no wagers. Baccarat earns +1 FP per completed round; new High-Low predictions earn +25 base XP for your correct guess and +1 FP for his correct guess. The native Level 52 bonus applies once.",
