  "chill.rules": "How to play",
  "chill.baccaratRules": "Cards: Ace = 1; 2–9 keep their value; 10/J/Q/K = 0. Hand totals use the last digit (modulo 10). Deal alternates Player, Banker, Player, Banker. An initial 8 or 9 on either side stops both hands. Otherwise Player draws on 0–5 and stands on 6–7. If Player stands, Banker draws on 0–5. If Player draws a third card x: Banker draws on 0–2; on 3 unless x = 8; on 4 with x = 2–7; on 5 with x = 4–7; on 6 with x = 6–7; and always stands on 7. Higher final total wins; equal totals push.",
  "chill.highlowRules": "Ace is high: 2–10, J, Q, K, A. Start and Next save his independent 50/50 Higher or Lower choice before your input; he never sees the hidden next card. New predictions require five eligible foreground seconds: hidden, modal, animation, offline and reload time never catches up. Your correct guess earns 25 base native XP; the Level 52 bonus applies once. A pending historical prediction keeps its old 10 base XP rate. His correct guess earns +1 FP. Equal ranks reward neither guess. No wagers or competitive score. A separate 52-card shoe is used; Next opens a fresh shoe after its last result. Saved results never pay again; closing or reloading preserves the table.",
  "chill.speechReady": "A quiet table, a few cards — let’s take our time.",
  "chill.speechBaccarat": "That round’s complete. I’m glad we’re playing together.",
  "chill.speechPrediction": "I’ve chosen my guess. What do you think comes next?",
  "chill.speechResult": "That card had its own plans. Ready when you are.",
  "interest.cap43.note": "Compound interest uses the current unspent XP bank at EVERY payment: native0.01% at actual20–25,0.015% at26–29,0.025% at30–79 unless a saved choice applies; earned timing/rates take over at80. No payment ceiling. Earned XP, physical Exp Joker and native Poker boosts apply once. One replay-stable critical roll per genuine payment: ×2 at50–61; 10% chance of×3 at62–99. Each native settlement retains level-up debits and uses the previous resulting bank. Actual100 earns0. Level15, manual22, Exp Potion and unrelated Slots boosts do not multiply interest. Knowledge and currency interest stay separate. Legacy receipts and balances remain unchanged. Eligible visible time only; no hidden/offline/reload catch-up.",
