  "app.literal.6c4ee82e9425": "Retry reading save",
  "app.literal.9b57ddb00a55": "Choose your save slot",
  "app.literal.813d421273bf": "Your original local progress is preserved as Slot 1. Slots 2 and 3 start fresh. Nothing plays or earns rewards until you choose.",
  "app.literal.653a171669d6": "Choose a slot to continue. You can switch or delete one later in Settings.",
  "app.literal.7fca14e85659": "Most played this round: not tracked in this save.",
