  "aux.potions.ui.76497c1847e2": "Doubles ordinary newly earned XP for120seconds, including faucet and surveys; compound interest and Knowledge keep their own rates. Stacks with the Level 15 XP bonus. Knowledge is a fixed-rate exception; old XP is never boosted retroactively.",
  "aux.potions.ui.cb2b708a3d5a": "Doubles ordinary listed probabilities for 120 seconds. Stacks with Level 17 luck and active physical Oops! All 6s. Potion drops cap at 50%; Boss Disabler stays fixed at 1 in 20. Shop rarity and edition rates are unchanged.",
  "aux.potions.ui.6fdf60fa4e43": "Each actual scoring-card trigger gives +4 Mult for 120 seconds, including retriggers. Unscored and held cards do not receive it.",
  "aux.potions.ui.1f1bb94bf5a8": "Each actual scoring-card trigger gives +20 Chips for 120 seconds, including retriggers. Unscored and held cards do not receive it.",
  "aux.potions.ui.1ca40d62f928": "Adds $5 once to each successful round-end payout during the 120-second effect. Cashing out or reloading never pays it again.",
  "aux.potions.ui.b6af75b2feae": "For 120 seconds, earn $1 interest per $3 held instead of per $5. Existing interest unlocks, caps and voucher rules still apply.",
  "aux.potions.ui.d5e72ea69f41": "Starts at 100 HP and gives a base 1 in 50 chance per actual scoring-card trigger to CRIT for ×2 current Mult for 120 seconds. Listed luck scales this chance. Each valid played hand loses HP equal to the exact number of selected cards, even if the Boss forbids scoring. At 0 HP the whole run is lost before any winning payout or drop, and Gaming ends. HP never heals on reload or a new run. Green >70; yellow ≤70; red ≤40.",
  "aux.potions.ui.72154f4523c9": "While an existing manually started Passive Exp session is paying, award exactly 1 XP per second for 120 seconds. This fixed award ignores Level15, Exp Potion and manual22; active physical Exp Jokers multiply it. It does not start, restart or extend a passive session.",
  "aux.potions.ui.c40d9ebf05c5": "Halves the current remaining passive-restart wait and coin-faucet wait once. An already-halved wait is never halved again by another bottle. New waits begun during the 120-second effect are also halved. Level 14 still applies. Expiry never lengthens a shortened deadline. Potion durations, animation and the Stock Market prediction deadline (10 real minutes) are NOT shortened.",
  "aux.potions.ui.bc48352ea84f": "Adds the current Atlantic/Canary day-of-month number as +Mult ONCE at the very end of scoring for 120 seconds. Example: on the 12th, +12 Mult — NOT ×12.",
  "aux.potions.ui.89b77ca324de": "Genuine Planet cards grant +1 extra poker-hand level per use for 120 seconds. Black Hole is Spectral and is NOT affected; Space Joker is not a Planet.",
  "aux.potions.ui.65a0409aa72b": "For 120 seconds, each actual scoring-card trigger, including retriggers, has a base 1 in 40 chance to CRIT for ×2 current Mult. Listed luck scales it. This is separate from Critical Joker; held, unscored or disabled cards never make this base roll.",
  "aux.potions.ui.7c1ae93425f7": "For 120 seconds, every non-Stone card qualifies as every suit for hand classification, Joker effects and Boss suit rules. Printed suits stay unchanged. Stone remains suitless.",
  "aux.potions.ui.d6fb8d60e36a": "One fixed 1 in 20 (5%) attempt at the start of an actual Boss while the 120-second effect is active. Luck and Oops NEVER boost this chance. A successful temporary disable ends when the potion expires, is replaced, or the Boss ends. No reroll on inspect, reload or clock sync; no once-per-run disable button.",
  "aux.potions.ui.ab4b3e6addc5": "Immediately grants +12 hand size; the bonus decreases by 1 every 10 real seconds: +12 → +11 → … → 0 at 120 seconds. In play, the initial increase can draw cards. Decay never deletes held cards; future refills respect the smaller capacity.",
  "aux.potions.ui.9e2cbb163003": "Player-level XP costs are 10% lower (×0.9, rounded up to whole XP, minimum 1) for 120 seconds. Already banked XP can earn levels immediately. Earned levels stay after expiry; no XP is fabricated or spent as a shop action.",
  "aux.potions.ui.4e20f747f47b": "Gift-only from Emerald Level 4+: 1% per genuine automatic speech, no more than once every 10 seconds. For 120 seconds, scoring animation durations are 30% shorter (×0.7). Stacks with Level 22 and your animation-speed preference; no score, money, gift odds or game timer changes. Original two inventory slots, one active potion, and merging rules still apply.",
  "aux.potions.ui.405f3924356e": "Exp Potion",
  "aux.potions.ui.6386f8f23c2f": "Double ordinary earned XP for2 minutes, including surveys and faucet; interest and Knowledge keep their own rates.",
  "aux.potions.ui.b6cbdd37c42c": "Luck Potion",
  "aux.potions.ui.4b6c6485feec": "Double listed luck for 2 minutes; Boss disabling stays fixed at 5%.",
  "aux.potions.ui.f88fa316ddb4": "Mult Potion",
  "aux.potions.ui.9284b1b9a03c": "Each actual scoring-card trigger adds +4 Mult for 2 minutes.",
  "aux.potions.ui.4035a0c701f9": "Chip Potion",
  "aux.potions.ui.b959c53f0c97": "Each actual scoring-card trigger adds +20 Chips for 2 minutes.",
  "aux.potions.ui.e3081600f2d7": "Money Potion",
  "aux.potions.ui.2134118f0c18": "Each successful round payout gains +$5 for 2 minutes.",
  "aux.potions.ui.49bbc3f63d91": "High Stonks Potion",
  "aux.potions.ui.8c62249fb0ed": "Interest uses $3 instead of $5 per interest dollar for 2 minutes, keeping its cap.",
  "aux.potions.ui.db147821757a": "Gaming Potion",
  "aux.potions.ui.6784a6c2628e": "Start at 100 HP; lose 1 HP per played card. 0 HP ends the run. Base CRIT is 1 in 50 for 2 minutes.",
  "aux.potions.ui.68832e1b8491": "Knowledge Potion",
  "aux.potions.ui.3aec02aba20f": "An existing passive session awards exactly 1 XP per second for 2 minutes, ignoring Level15, manual22 and Exp Potion; active physical Exp Jokers still multiply it.",
  "aux.potions.ui.50881c7cbfa2": "Cooldown Potion",
  "aux.potions.ui.46ad942d902b": "Halve passive restart and coin faucet waits for 2 minutes; no potion or prediction timer changes.",
  "aux.potions.ui.9f94a7d48e5b": "Daylight Potion",
  "aux.potions.ui.e2184861d0f0": "Add the current Canary Islands day of the month to Mult at the very end of scoring for 2 minutes.",
  "aux.potions.ui.c5dff83ed540": "Night Potion",
  "aux.potions.ui.677a1e371b48": "Each genuine Planet use grants 1 extra hand level for 2 minutes (not Black Hole or Space Joker).",
  "aux.potions.ui.2ca2749fdba0": "Critical Potion",
  "aux.potions.ui.ac2827dfac01": "Base CRIT is 1 in 40 per actual scoring-card trigger for 2 minutes; each CRIT gives X2 current Mult.",
  "aux.potions.ui.d902fe88bc4f": "All-Suiter",
  "aux.potions.ui.28c4c470e886": "Every non-Stone card counts as every suit for 2 minutes without changing its printed suit.",
  "aux.potions.ui.cf14a56d475e": "Boss-disabler Potion",
  "aux.potions.ui.4e8bff3f2e22": "Fixed 1 in 20 chance to disable an actual Boss at its start, only until this potion ends.",
  "aux.potions.ui.175c5e58a879": "Turtle Potion",
  "aux.potions.ui.0f8e7708f6ea": "Start at +12 hand size, losing 1 every 10 seconds for 2 minutes; excess held cards are kept.",
  "aux.potions.ui.0c8c82342ee1": "Exp for Discounts Potion",
  "aux.potions.ui.529e725fe1be": "Player XP level costs are 10% lower for 2 minutes; earned levels remain afterwards.",
  "aux.potions.ui.31f13835a259": "Speed Potion",
  "aux.potions.ui.5c0dd5763ec0": "Scoring animation durations are multiplied by 0.7 for 2 minutes. Emerald gift only; no scoring, gameplay clock or cooldown changes.",
