  "aux.levels.ui.298aaf6a33a2": "After reaching Level {value1}: win Small, Big and Boss in order in the same run and Ante. Skipped Blinds never count. The next cap starts a fresh counter. All XP stays saved.",
  "aux.levels.ui.12b50fb8ec34": "{value1} to unlock cap {value2}",
  "aux.levels.ui.cc419e152ce7": "Current cap: {value1}. {value2} Each complete Ante requires Small, Big and Boss WIN receipts in order in the same run and Ante; skipped Blinds never count. Each cap starts fresh: 10 / 25 / 50 / 100 complete Antes after reaching Levels 10 / 20 / 30 / 35. Existing earned levels and caps stay unlocked; no historic whole-Ante credit is invented. All XP stays saved.",
