  "aux.levels.ui.ff75e0d3a881": "{value1} Current bank: {value2} XP; next second: {value3} actual XP. Colour stays neutral through 1 XP/sec, gradually reaches yellow at 2 XP/sec, then grows greener up to 5 XP/sec.{value4}{value5}{value6}{value7}",
  "aux.levels.ui.f56e82a7ade0": "Moving Mode · save movable-panel layouts · Custom table themes · All levels XP required halved · {value1}",
  "aux.levels.ui.fd983ce532d1": "Better Player Levels UI · clearer XP, rewards and completed / locked states · green +XP gain animations and a bouncing white XP-bar shine · {value1}",
  "aux.levels.ui.6ee23633b64b": "Future XP costs another40% lower, stacking with Level10 (30% of original costs); no refunds · +1 hand and discard on every Boss · Cleaner UI and smoother buttons · richer colors and soft glows · dollar amounts yellow · Small Blind blue, Big Blind yellow, Boss Blind red · {value1}",
  "aux.levels.ui.9cf1b5d5fea3": "{value1} · Future XP costs an extra30% lower from 30→31 onward; stacks with Level10 halving and Level20 reduction (21% of original before integer rounding and potions); no refunds · Custom face-card photos (J/Q/K) · Enhanced UI and richer table colors · Upload your own background and card-back images · Customize every text font and color in Settings; reset text without changing photos or panel layouts",
  "aux.levels.ui.2eb04acd9701": "Maximum player level {value1} reached. Earlier rewards stay active.",
