  "aux.levels.ui.e445541d4be7": "Extra colour shine · static blue, red, gold and green highlights; original colours, readable text and motion settings stay intact",
  "aux.levels.ui.5dae15c973e6": "More dramatic Boss music · developing tension, moving harmony and tense rhythms, with a stronger final-boss climax",
  "aux.levels.ui.1a62db1746a4": " · Emerald companion available: your supplied beetle photo, game-only tips and encouragement",
  "aux.levels.ui.5e10e5839a2d": " · Emerald progression unlocked: green E1–E10 bar below the photo during a run; fresh full-game wins earned at actual Level10+ advance each stage",
  "aux.levels.ui.15734bbd0c0d": " · Frenzy unlocked: 500 genuinely scored card triggers activate 10 seconds of rainbow Frenzy and ×1.5 final Mult (166 triggers from Level35)",
  "aux.levels.ui.f54a86a01acf": " · Six base Joker slots · Select up to 6 cards to play or discard · Frenzy now needs 166 genuinely scored card triggers · Double-Triple of a Kind: 120 Chips ×10 Mult, +20 Chips/+4 Mult per level; Venus Rock · Six of a Kind: 150 Chips ×10 Mult, +30 Chips/+3 Mult per level; Planet Y",
  "aux.levels.ui.92fb25712016": "Music unlocked · Change username in Settings → Change username → Confirm",
  "aux.levels.ui.cc4d1a7109e9": "Interest unlocked · Cleaner game layout: compact stats, grouped Run / Tools controls and more room for cards",
  "aux.levels.ui.c3986e8d8c85": "Four base Joker slots",
  "aux.levels.ui.2ec3a602bafa": "Five base Joker slots · Emotional music unlocked: Last Chance",
  "aux.levels.ui.80220b003c53": "Smart number abbreviations",
  "aux.levels.ui.a6831b469325": "Manual passive XP · 0.01/sec, 10-minute session, then 5-minute cooldown",
  "aux.levels.ui.1bbfd47eb010": "Passive XP increases to 0.025 every second for 10-minute sessions, then a 5-minute cooldown",
  "aux.levels.ui.14471419e112": "Potions unlocked · hold 2, drink for a 2-minute effect. Boss wins: base 1 in 10 drop chance, capped at 5 in 10.",
  "aux.levels.ui.7909190c155b": "Passive XP sessions last 20 minutes",
  "aux.levels.ui.20ad162e567b": "Unlock Theorem Reach Surveys · Passive XP cooldown reduced to 4 minutes",
  "aux.levels.ui.c9cf9b6a4705": "Double XP from now on",
  "aux.levels.ui.2ef761428a63": "Passive XP sessions last 30 minutes · Base passive XP increases to 0.05/sec (0.1 XP/sec with Level 15 double XP)",
  "aux.levels.ui.00991737774c": "Permanent +25% luck · listed probabilities ×1.25; stacks with Oops and caps at 100%",
  "aux.levels.ui.6251513eba38": "Unlock Bitlabs Surveys · Earn $1 each time an active Boss special effect triggers · one reward per ability activation, not per affected card",
  "aux.levels.ui.62ea740ddc00": "Stock Market · fictional game-dollar predictions using public Binance BTC prices; no real money",
  "aux.levels.ui.5ce6478a32d8": "Animations20% quicker · +20% manual XP (gameplay, surveys and faucet); not passive, Knowledge or interest",
  "aux.levels.ui.4c33d5827537": "+$1 at every cleared-round cashout",
  "aux.levels.ui.b22c96f74381": "Everything in the run shop costs $1 less, after existing discounts; floor $0 · Casino soundtrack unlocked",
  "aux.levels.ui.ff12575787c7": "Unlock CPX Research Surveys · Coin faucet · base10 XP per successful claim, with manual22, Exp Potion and Exp Jokers (not Level15). Starts at 50% task rate; reach Ante 4 in 1 qualifying run each day for full task rate. Repeated claims reduce the daily claim tier.",
  "aux.levels.ui.7b8c17e2aa43": "Compound interest improves to current bank ×0.015%, with no payment ceiling",
  "aux.levels.ui.e05cf7cff27b": "Two more original soundtracks: Starlight Felt and Copper Groove",
  "aux.levels.ui.20bfdc60ebb9": "Non-spam in-game faucet-ready notification; no browser permissions",
  "aux.levels.ui.4e8ce5229a16": "Five original decks and two original stakes unlock on the main screen",
  "aux.levels.ui.1982d56e4324": "Fullscreen and exit controls; OS minimizing remains a device control",
  "aux.levels.ui.0b02333ddd7f": "Merge two stored potions, retaining both effects for one120-second lifetime",
  "aux.levels.ui.268db3145f3b": "+$2 at the end of every cleared round",
  "aux.levels.ui.172c3a8a5b8f": "Emerald: tap the photo or progress bar for her own roadmap, with the current level bordered; fresh-win progress and percentage · Auto Speak for 5 minutes, then 1 minute cooldown · George Street Shuffle and Mining by Moonlight licensed recordings; Poker Face opens the exact official Spotify track externally, not offline audio",
  "aux.levels.ui.4091e1349b2d": "Emerald reflects a stronger emerald-green shine",
  "aux.levels.ui.c0955075c2a3": "Emerald appears on every screen, including surveys · Exactly “Trick Question!!!” only on a genuine attention-check question",
  "aux.levels.ui.7d1c4602dc17": "Passive Money below Coin faucet, matching the Passive XP layout with a yellow glow and $ € £ symbols · +$0.01 per observable foreground second into the current-run Bank for 10 minutes, then 5 minutes cooldown · Higher Bank gives a higher-pitched money sound; no offline catch-up",
  "aux.levels.ui.67a11fa93b06": "Richer textured colours, reflected lights, cleaner interface and extra shine; question ink and survey answer media stay unchanged",
  "aux.levels.ui.ec808c9444d1": "Passive Money sessions last 20 minutes, then 4 minutes cooldown; existing sessions keep their captured duration",
  "aux.levels.ui.d45192c949dd": "Permanent +1 hand size; no free immediate draw, extra selection or Joker slot",
