  "aux.surveys.ui.836a7950a71c": "Base rewards · 10–20 coins or Medals, or 100–300 base XP. Local simulated events occasionally boost NEW offers only. Promoted rewards round up to the next 0.5 game unit; already included in the listed reward.",
  "aux.surveys.ui.02f7055f0f8c": "Each offer independently chooses coins, Medals or XP with a 1 in 3 chance. XP shown is BASE XP; unlocked Level 15 / Level 22 manual-XP bonuses, owned Exp Joker and active Exp Potion bonuses apply when banked.",
  "aux.surveys.ui.ae31f241d489": "Stars set the questionnaire look and media quality: 1★ rough draft, 2★ basic, 3★ standard, 4★ polished, 5★ studio. Low-star answer text can be sharpened. New questionnaires begin with a local CAPTCHA, then Welcome to the Survey! Old saved questionnaires keep their original questions.",
  "aux.surveys.ui.679d81586b02": "HOT / New · Recently added: 1 in 5, label only. TOP · 4× provider reward: 1 in 25, already included below. Independent badges can appear together; TOP adds no questions.",
