  "aux.stats.ca04e0349f22": "One active bottle for2 real minutes. Level33 blends preserve all distinct effects for one shared lifetime; Gaming+Critical add4.5% potion base CRIT. Final odds cap100%. Boss drops are capped at 5 in 10; Boss-disabler Potion stays fixed at 1 in 20. Market prediction timers are not cooldowns.",
