  "aux.stats.b70edc427fba": "Session remaining",
  "aux.stats.84d8669b9135": "Level 9: 0.01 XP per second. Levels 11–15: 0.025 base XP per second; Level 16+: 0.05 base XP per second until Level 20. Passive XP is doubled from Level 15, so Level 16 gives 0.1 XP per second. Compound interest uses the current unspent XP bank at EVERY payment: native0.01% at actual20–25,0.015% at26–29,0.025% at30–79 unless a saved choice applies; earned timing/rates take over at80. No payment ceiling. Earned XP, physical Exp Joker and native Poker boosts apply once. One replay-stable critical roll per genuine payment: ×2 at50–61; 10% chance of×3 at62–99. Each native settlement retains level-up debits and uses the previous resulting bank. Actual100 earns0. Level15, manual22, Exp Potion and unrelated Slots boosts do not multiply interest. Knowledge and currency interest stay separate. Legacy receipts and balances remain unchanged. Eligible visible time only; no hidden/offline/reload catch-up. New sessions last 10 minutes until Level 13, then20/30/50/60 minutes at Levels13/16/33/44; Level22 no longer extends sessions. Five-minute cooldown until Level 14, then four minutes; reaching Level 14 also shortens a current cooldown. No automatic restart. Exp Potion doubles ordinary passive XP; Knowledge earns1 XP per second times active physical Exp Jokers only; Level15, Exp Potion and manual Level22 are excluded. Cooldown Potion can halve a wait once, never stack it to a quarter.",
