  "aux.emerald.blackjack.ui.7eb66e5118fc": "MAX · {value1} FP",
  "aux.emerald.blackjack.ui.bfb414bf51ab": "{value1}/{value2} FP",
  "aux.emerald.blackjack.ui.f789c4eb21db": " FP remaining to Friendship Lv {value1}",
  "aux.emerald.blackjack.ui.472984585f76": "Face-down card",
  "aux.emerald.blackjack.ui.2d19dec9aa43": "Ready for the deal",
  "aux.emerald.blackjack.ui.9bf2be15acf2": "Ready when you are. Win a round to earn 1 point.",
  "aux.emerald.blackjack.ui.b2916229c20a": "Beat Emerald without going over 21 to earn 1 point.",
  "aux.emerald.blackjack.ui.42ea85436e9f": " Lovely playing together — that was your round!",
  "aux.emerald.blackjack.ui.a475b3488a5a": " I’m glad we’re playing together. Take your time on the next one.",
  "aux.emerald.blackjack.ui.fc8123bdfb07": " You’ve got this. Let’s enjoy the next move together.",
  "aux.emerald.blackjack.ui.eecdfe7bdb54": " Your move paid off!",
  "aux.emerald.blackjack.ui.2fb42ac6ba05": " My round! Ready for another?",
  "aux.emerald.blackjack.ui.04a01324d5b2": " Let’s see what your next move brings.",
  "aux.emerald.blackjack.ui.40c7f8e473c9": "Friendship Lv",
  "aux.emerald.blackjack.ui.433af78c1585": "0 FP remaining · Maximum friendship reached",
  "aux.emerald.blackjack.ui.5bf09aa55c26": " FP remaining to maximum friendship",
  "aux.emerald.blackjack.ui.0da47fae032a": "Emerald Lv",
  "aux.emerald.blackjack.ui.ecfb23c5e950": "Saved earlier round:",
  "aux.emerald.blackjack.ui.366da13a6382": "this round keeps its original 21-only scoring and saved result. Normal Blackjack starts with your next deal; your existing match points and friendship are kept.",
  "aux.emerald.blackjack.ui.1892c889ec14": "How to play Blackjack",
  "aux.emerald.blackjack.ui.9a61529ef7cb": "Goal:",
  "aux.emerald.blackjack.ui.05620ebe2577": "beat Emerald by getting closer to 21 without going over. A higher non-bust total wins; if your opponent busts, you win. Going over 21 is a bust and immediately loses your round. Equal totals are a push (tie).",
  "aux.emerald.blackjack.ui.2cb86993fe85": "Card values:",
  "aux.emerald.blackjack.ui.73a6d3a088c6": "number cards 2–10 count at face value; Jack, Queen and King count as 10. An Ace counts as 11 or 1, whichever keeps your best total without busting. A soft hand has an Ace still counted as 11.",
  "aux.emerald.blackjack.ui.bd5c7b75fc4f": "The deal:",
  "aux.emerald.blackjack.ui.4a70e9efecbf": "you and Emerald receive two cards each, with one Emerald card face down. An opening Ace plus a 10-value card is a natural Blackjack: it beats an ordinary 21 made with more cards. Two natural Blackjacks push; a sole natural wins immediately.",
  "aux.emerald.blackjack.ui.db0129e4cf75": "Your turn:",
  "aux.emerald.blackjack.ui.bd063fccfe84": "Hit takes another card. Stand keeps your hand and ends your turn. You may hit again until you stand, bust, or reach 21. Reaching 21 ends your turn and resolves Emerald’s hand; it is not an automatic win if Emerald also reaches 21.",
  "aux.emerald.blackjack.ui.5668f90fc8d0": "Emerald’s turn:",
  "aux.emerald.blackjack.ui.4d4dbf95e3b1": "the hidden card is revealed; Emerald hits below 17 and stands on 17 or higher, including soft 17. After both hands finish, the higher non-bust total wins. If you already bust, the round ends without another Emerald turn.",
  "aux.emerald.blackjack.ui.86f4fca99153": "Match scoring:",
  "aux.emerald.blackjack.ui.17f2300a3af2": "every round win earns 1 point, even below 21. A push earns no point. First to 10 points wins the match. Every completed round—win, loss or push—earns you +1 Friendship Point (FP). Opening a tab, leaving or reloading never grants another FP.",
  "aux.emerald.blackjack.ui.54406fb8245f": "Friendly table, no wagers:",
  "aux.emerald.blackjack.ui.bbb0975a9344": "the casino bets, 1:1 or 3:2 payouts, Double Down, Split, Surrender and Insurance shown in the reference rules are not used here. Blackjack never spends or awards your poker Bank.",
  "aux.emerald.blackjack.ui.0291d43cec31": "Passive Money:",
  "aux.emerald.blackjack.ui.8028b08cabd4": "when unlocked and activated, it still adds $0.01 per eligible foreground second to your poker Bank, including in this tab. Hidden or locked-screen time and save/modal-protected pauses do not earn money.",
  "aux.emerald.blackjack.ui.c7a8d07745b6": "No active poker run",
  "aux.emerald.blackjack.ui.ae642d0e74ee": "Deal",
  "aux.emerald.blackjack.ui.8a043f55ef38": "Hit",
  "aux.emerald.blackjack.ui.2de251e0c4e8": "Stand",
