  "aux.emerald.blackjack.ui.ff1dc06797ea": "Emerald’s table · no wagers",
  "aux.emerald.blackjack.ui.286116285a09": "to 10",
  "aux.emerald.blackjack.ui.230e62edbe61": "Normal Blackjack · win a round for 1 point · first to 10. Ties earn no point. Every completed round earns +1 FP. Emerald stands on 17, including soft 17.",
  "aux.emerald.blackjack.ui.2fc7b3ef080a": "Leave Blackjack and keep this table",
