  "catalog.potions.all_suiter.activeDetail": "Every non-Stone card qualifies as every suit",
  "catalog.potions.all_suiter.description": "For 120 seconds, every non-Stone card qualifies as every suit for hand classification, Joker effects and Boss suit rules. Printed suits stay unchanged. Stone remains suitless.",
  "catalog.potions.all_suiter.name": "All-Suiter",
  "catalog.potions.blend.activeDetail": " · Combined potion CRIT4.5% base; Level32 adds1pp; final odds cap100%.",
  "catalog.potions.boss_disabler.activeDetail": "Fixed 1 in 20 at Boss start · temporary disable",
  "catalog.potions.boss_disabler.description": "One fixed 1 in 20 (5%) attempt at the start of an actual Boss while the 120-second effect is active. Luck and Oops NEVER boost this chance. A successful temporary disable ends when the potion expires, is replaced, or the Boss ends. No reroll on inspect, reload or clock sync; no once-per-run disable button.",
  "catalog.potions.boss_disabler.name": "Boss-disabler Potion",
  "catalog.potions.chips.activeDetail": "+20 Chips / scoring-card trigger",
  "catalog.potions.chips.description": "Each actual scoring-card trigger gives +20 Chips for 120 seconds, including retriggers. Unscored and held cards do not receive it.",
  "catalog.potions.chips.name": "Chip Potion",
  "catalog.potions.cooldown.activeDetail": "½ new passive / faucet waits · Existing market deadlines stay unchanged.",
  "catalog.potions.cooldown.description": "Halves the current remaining passive-restart wait and coin-faucet wait once. An already-halved wait is never halved again by another bottle. New waits begun during the 120-second effect are also halved. Level 14 still applies. Expiry never lengthens a shortened deadline. Potion durations, animation and accepted Stock Market deadlines are NOT shortened (new predictions: 10 minutes before Level40, 60 seconds from Level40).",
  "catalog.potions.cooldown.name": "Cooldown Potion",
  "catalog.potions.critical.activeDetail": "2.5% base CRIT · {value1}% now / scoring trigger · ×2 Mult",
  "catalog.potions.critical.description": "For 120 seconds, each actual scoring-card trigger, including retriggers, has a base 1 in 40 chance to CRIT for ×2 current Mult. Listed luck scales it. This is separate from Critical Joker; held, unscored or disabled cards never make this base roll.",
  "catalog.potions.critical.name": "Critical Potion",
  "catalog.potions.daylight.activeDetail": "+{value1} Mult at scoring END · not ×day",
  "catalog.potions.daylight.description": "Adds the current Atlantic/Canary day-of-month number as +Mult ONCE at the very end of scoring for 120 seconds. Example: on the 12th, +12 Mult — NOT ×12.",
  "catalog.potions.daylight.name": "Daylight Potion",
  "catalog.potions.exp.activeDetail": "×2 newly earned XP",
  "catalog.potions.exp.description": "Doubles ordinary newly earned XP for120seconds, including faucet and surveys; compound interest and Knowledge keep their own rates. Stacks with the Level 15 XP bonus. Knowledge is a fixed-rate exception; old XP is never boosted retroactively.",
  "catalog.potions.exp.name": "Exp Potion",
  "catalog.potions.gaming.activeDetail": "2% base CRIT · {value1}% now · lose 1 HP / selected card",
  "catalog.potions.gaming.description": "Starts at 100 HP and gives a base 1 in 50 chance per actual scoring-card trigger to CRIT for ×2 current Mult for 120 seconds. Listed luck scales this chance. Each valid played hand loses HP equal to the exact number of selected cards, even if the Boss forbids scoring. At 0 HP the whole run is lost before any winning payout or drop, and Gaming ends. HP never heals on reload or a new run. Green >70; yellow ≤70; red ≤40.",
  "catalog.potions.gaming.name": "Gaming Potion",
  "catalog.potions.high_stonks.activeDetail": "$1 interest / $3 held · normal cap",
  "catalog.potions.high_stonks.description": "For 120 seconds, earn $1 interest per $3 held instead of per $5. Existing interest unlocks, caps and voucher rules still apply.",
  "catalog.potions.high_stonks.name": "High Stonks Potion",
  "catalog.potions.knowledge.activeDetail": "Fixed 1 XP / second · manual Passive Exp only",
  "catalog.potions.knowledge.description": "While an existing manually started Passive Exp session is paying, award exactly 1 XP per second for 120 seconds. This fixed award ignores Level15, Exp Potion and manual22; active physical Exp Jokers multiply it. It does not start, restart or extend a passive session.",
  "catalog.potions.knowledge.name": "Knowledge Potion",
  "catalog.potions.luck.activeDetail": "×2 listed luck · drops capped at 50%",
  "catalog.potions.luck.description": "Doubles ordinary listed probabilities for 120 seconds. Stacks with Level 17 luck and active physical Oops! All 6s. Potion drops cap at 50%; Boss Disabler stays fixed at 1 in 20. Shop rarity and edition rates are unchanged.",
  "catalog.potions.luck.name": "Luck Potion",
  "catalog.potions.money.activeDetail": "+$5 / cleared round",
  "catalog.potions.money.description": "Adds $5 once to each successful round-end payout during the 120-second effect. Cashing out or reloading never pays it again.",
  "catalog.potions.money.name": "Money Potion",
  "catalog.potions.mult.activeDetail": "+4 Mult / scoring-card trigger",
  "catalog.potions.mult.description": "Each actual scoring-card trigger gives +4 Mult for 120 seconds, including retriggers. Unscored and held cards do not receive it.",
  "catalog.potions.mult.name": "Mult Potion",
  "catalog.potions.night.activeDetail": "+1 extra level / Planet · not Black Hole",
  "catalog.potions.night.description": "Genuine Planet cards grant +1 extra poker-hand level per use for 120 seconds. Black Hole is Spectral and is NOT affected; Space Joker is not a Planet.",
  "catalog.potions.night.name": "Night Potion",
  "catalog.potions.replaceConfirmation.1": "Your active {value1} has {clock} remaining. Its effect ends immediately, with no refund.",
