  "catalog.potions.replaceConfirmation.8": "Your active {value1} + {value2} + {value3} + {value4} + {value5} + {value6} + {value7} + {value8} has {clock} remaining. Its effect ends immediately, with no refund.",
  "catalog.potions.replaceConfirmation.9": "Your active {value1} + {value2} + {value3} + {value4} + {value5} + {value6} + {value7} + {value8} + {value9} has {clock} remaining. Its effect ends immediately, with no refund.",
  "catalog.potions.speed.activeDetail": "Scoring animation durations ×0.7 · no score or timer change",
  "catalog.potions.speed.description": "Gift-only from Emerald Level 4+: 1% per genuine automatic speech, no more than once every 10 seconds. For 120 seconds, scoring animation durations are 30% shorter (×0.7). Stacks with Level 22 and your animation-speed preference; no score, money, gift odds or game timer changes. Inventory: two slots before Level40, three at40, four at47. One active potion and original merging rules still apply.",
  "catalog.potions.speed.name": "Speed Potion",
  "catalog.potions.turtle.activeDetail": "+{value1} hand size · −1 every 10 real seconds",
  "catalog.potions.turtle.description": "Immediately grants +12 hand size; the bonus decreases by 1 every 10 real seconds: +12 → +11 → … → 0 at 120 seconds. In play, the initial increase can draw cards. Decay never deletes held cards; future refills respect the smaller capacity.",
  "catalog.potions.turtle.name": "Turtle Potion",
  "catalog.potions.xp_discount.activeDetail": "Player XP costs ×0.9 · earned levels stay",
  "catalog.potions.xp_discount.description": "Player-level XP costs are 10% lower (×0.9, rounded up to whole XP, minimum 1) for 120 seconds. Already banked XP can earn levels immediately. Earned levels stay after expiry; no XP is fabricated or spent as a shop action.",
  "catalog.potions.xp_discount.name": "Exp for Discounts Potion",
