  "uiC.food.footerPurchase": "Purchases activate when the next Blind starts. Foods stack up to three distinct plates. Coupons last through the following Shop; free native offers stay free.",
  "uiC.food.footerRules": "Tickets belong to this run, not Bank dollars. No offline or skipped-Blind tickets. Food scoring resolves once: flat Chips/Mult, then factors, before Frenzy and final-score boosts. Native Boss and zero-resource locks win.",
  "uiC.food.intro": "Three plates. One ticket each. Every bite has a catch.",
