  "uiC.hand.levelShort": "Lvl {n}",
  "uiC.help.audio": "The first tap enables original lounge music and card/scoring sounds. Tap the music button or press M to mute; Settings has separate music/effects controls and volume sliders. There are no audio downloads.",
  "uiC.help.audioLabel": "Audio:",
  "uiC.help.bosses": "Bosses have special rules. Read them before committing.",
  "uiC.help.controls": "Tap a Joker to inspect. Hold a playing card for its details. Use the inspection sheet's arrows to reorder. Press I on a focused card to inspect it. Sort buttons reorder your hand.",
  "uiC.help.controlsLabel": "Controls:",
  "uiC.help.discard": "Discard up to {limit} cards at a time to look for a better hand.",
  "uiC.help.fileHint": "Downloaded-file previews use browser-dependent storage. Export backups and use the same hosted URL for reliable continuation.",
  "uiC.help.formula": "Chips × Mult",
  "uiC.help.goalBlinds": "8 Antes × 3 blinds",
  "uiC.help.goalEnd": ": Small, Big and Boss. Beat Ante 8's Boss to win.",
  "uiC.help.goalStart": "Score enough points before your hands run out. A run has",
  "uiC.help.order": "before-play effects → scoring cards and their retriggers → held-in-hand effects → independent Jokers. +Mult before ×Mult helps only when the effects share a timing window.",
  "uiC.help.orderLabel": "Scoring order:",
  "uiC.help.planets": "Planets level up hands; Jokers change how you score.",
  "uiC.help.play": "Play hand",
  "uiC.help.potionGuide": "How to Use · all 16 potion effects",
  "uiC.help.potions": "Store two bottles, with only one active effect for exactly 120 real seconds. Inspecting never drinks. An explicit confirmation is required, including replacement. Boss drops start at 1 in 10 and cap at 50% with luck; Boss Disabler stays fixed at 1 in 20. Timers and Gaming HP persist through reload and new runs.",
  "uiC.help.potionsLabel": "Potions · Level 12:",
  "uiC.help.save": "Progress and statistics save automatically in this browser. Download/export a backup in Settings. This is a single-player, local-first foundation—not multiplayer or an official Balatro product.",
  "uiC.help.saveLabel": "Save:",
  "uiC.help.score": "Score =",
  "uiC.help.scoringCards": "Only cards belonging to the poker hand normally score.",
  "uiC.help.select": "Tap 1–{limit} cards, then",
  "uiC.help.shop": "After a win, cash out and improve your deck at the shop. Skipping Small/Big trades the round and shop for a tag.",
  "uiC.help.title": "The rules of the table",
