  "uiC.recovery.export": "Export recovery evidence",
  "uiC.recovery.note": "Do not retry the action or clear data. Reload checks retained journals before models load. Read-only evidence export does not repair or change any bank.",
  "uiC.restore.confirm": "Restore all three from backup",
  "uiC.restore.keep": "Keep current saves",
  "uiC.restore.summary": "This replaces ALL THREE current local saves with the verified pre-ending saves, and captures the complete newer saves in a DIFFERENT lasting backup first. The original backup is never overwritten. The restored optional story is disabled so the ending cannot replay. Restore is refused after any of the three target generations has been independently replaced.",
  "uiC.restore.title": "Restore ALL THREE saves?",
  "uiC.restore.typed": "Type RESTORE ALL 3 exactly",
  "uiC.rewards.after.aux.levels.ui.9cf1b5d5fea3": " · Future XP costs an extra30% lower from 30→31 onward; stacks with Level10 halving and Level20 reduction (21% of original before integer rounding and potions); no refunds · Custom face-card photos (J/Q/K) · Enhanced UI and richer table colors · Upload your own background and card-back images · Customize every text font and color in Settings; reset text without changing photos or panel layouts",
  "uiC.rewards.beetle.aux.levels.ui.172c3a8a5b8f": "a green beetle: tap the photo or progress bar for her own roadmap, with the current level bordered; fresh-win progress and percentage · Auto Speak for 5 minutes, then 1 minute cooldown · George Street Shuffle and Mining by Moonlight licensed recordings; Poker Face opens the exact official Spotify track externally, not offline audio",
  "uiC.rewards.beetle.aux.levels.ui.4091e1349b2d": "a green beetle reflects a stronger emerald-green shine",
  "uiC.rewards.beetle.aux.levels.ui.5e10e5839a2d": " · a green beetle progression unlocked: green E1–E10 bar below the photo during a run; fresh full-game wins earned at actual Level10+ advance each stage",
  "uiC.rewards.beetle.aux.levels.ui.c0955075c2a3": "a green beetle appears on every screen, including surveys · Exactly “Trick Question!!!” only on a genuine attention-check question",
  "uiC.rewards.beetle.emerald.quirk.unlock": "From player Level 6, each new a green beetle message has a 1 in 6 chance of one text-only quirk, chosen equally from six sounds — including Blackjack. No audio.",
  "uiC.rewards.beetle.expansion.reward.48": "a green beetle moves 50% faster in addition to his own E3 speed: ×1.5, or ×1.8 with E3. Motion preferences still apply. With no saved custom choice, native interest is600 ms at ×0.025%, no payment ceiling. A saved choice overrides native timing/rate; the Settings row edits the same ONE stream. Actual100 earns0.",
  "uiC.rewards.beetle.expansion.reward.49": "a green beetle gains over 1,000 additional original contextual messages in English, Spanish and French: cards, games, kind reflections and respectful Bible-inspired ideas. Survey-completion remarks require a real saved completion; no hidden-card or RNG predictions.",
  "uiC.rewards.beetle.uiC.rewards.companion5": " · a green beetle companion: game tips and encouragement",
  "uiC.rewards.before.aux.levels.ui.6ee23633b64b": "Future XP costs another40% lower, stacking with Level10 (30% of original costs); no refunds · +1 hand and discard on every Boss · Cleaner UI and smoother buttons · richer colors and soft glows · dollar amounts yellow · Small Blind blue, Big Blind yellow, Boss Blind red · ",
  "uiC.rewards.before.aux.levels.ui.f56e82a7ade0": "Moving Mode · save movable-panel layouts · Custom table themes · All levels XP required halved · ",
  "uiC.rewards.before.aux.levels.ui.fd983ce532d1": "Better Player Levels UI · clearer XP, rewards and completed / locked states · green +XP gain animations and a bouncing white XP-bar shine · ",
  "uiC.rewards.companion5": " · Emerald companion: game tips and encouragement",
  "uiC.rewards.crit": "Permanent +1% CRIT per actual scoring card trigger",
  "uiC.rewards.late.100": "Maximum Level100! Continue this save or explicitly start Savefile2.",
  "uiC.rewards.late.56": "The Coin Faucet no longer asks a Balatro question. CAPTCHA remains.",
  "uiC.rewards.late.57": "+10% relative luck (x1.10 on earned x1.25 = x1.375).",
  "uiC.rewards.late.58": "Ten more original soundtracks.",
  "uiC.rewards.late.59": "Normal starting run money is $10. Yellow and Erratic special starts stay special.",
  "uiC.rewards.late.60": "Foods and Darts. Earn one food ticket for every two completed Antes; View the bar in the shop.",
  "uiC.rewards.late.61": "Cleaner, more readable game and card-game tables.",
  "uiC.rewards.late.62": "More fonts to personalise your table.",
  "uiC.rewards.late.80": "Earned interest takes over; Interest and Feature power Settings sections are retired without deleting saved choices.",
