  "uiC.rewards.unknown.aux.levels.ui.172c3a8a5b8f": "???: tap the photo or progress bar for her own roadmap, with the current level bordered; fresh-win progress and percentage · Auto Speak for 5 minutes, then 1 minute cooldown · George Street Shuffle and Mining by Moonlight licensed recordings; Poker Face opens the exact official Spotify track externally, not offline audio",
  "uiC.rewards.unknown.aux.levels.ui.4091e1349b2d": "??? reflects a stronger emerald-green shine",
  "uiC.rewards.unknown.aux.levels.ui.5e10e5839a2d": " · ??? progression unlocked: green E1–E10 bar below the photo during a run; fresh full-game wins earned at actual Level10+ advance each stage",
  "uiC.rewards.unknown.aux.levels.ui.c0955075c2a3": "??? appears on every screen, including surveys · Exactly “Trick Question!!!” only on a genuine attention-check question",
  "uiC.rewards.unknown.emerald.quirk.unlock": "From player Level 6, each new ??? message has a 1 in 6 chance of one text-only quirk, chosen equally from six sounds — including Blackjack. No audio.",
  "uiC.rewards.unknown.expansion.reward.48": "??? moves 50% faster in addition to his own E3 speed: ×1.5, or ×1.8 with E3. Motion preferences still apply. With no saved custom choice, native interest is600 ms at ×0.025%, no payment ceiling. A saved choice overrides native timing/rate; the Settings row edits the same ONE stream. Actual100 earns0.",
  "uiC.rewards.unknown.expansion.reward.49": "??? gains over 1,000 additional original contextual messages in English, Spanish and French: cards, games, kind reflections and respectful Bible-inspired ideas. Survey-completion remarks require a real saved completion; no hidden-card or RNG predictions.",
  "uiC.rewards.unknown.uiC.rewards.companion5": " · ??? companion: game tips and encouragement",
  "uiC.rewards.updated.19": "Bitlabs surveys · All newly opened packs offer one extra option, not an extra pick. Replaces the $1 Boss-special reward.",
  "uiC.rewards.updated.3": "Colourful level-up window with blue up arrows",
  "uiC.rewards.updated.31": "+10% Balatro action XP only · View Abandoned Run gives factual advice from that run",
  "uiC.rewards.updated.34": "Richer statistics, colourful tabs and evidence-based Insights",
  "uiC.rewards.updated.40": "Future XP costs −20%, except reaching Level50 · Store3 potions · New stock predictions60s · Five-character faucet CAPTCHA · Richer owner-level progress colours",
  "uiC.rewards.updated.47": "Store4 potions · Stock Market max stake game$20; predictions accepted from Level40 last60s, old pending deadlines stay unchanged",
  "uiC.rewards.updated.50": "Another −10% future XP costs; Level40 remains active · Player maximum100 · Games, Strict Poker and Slots",
  "uiC.rewards.updated.6": "New runs start with $5 instead of $4",
